def main(dest):
    root=pathlib.Path(dest)
    for name,content in SRC.items():
        path=root/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content+'\n',encoding='utf-8')
    print('wrote',len(SRC),'compile-only stubs to',root)
if __name__=='__main__':
    if len(sys.argv)!=2:raise SystemExit('usage: gen_api246.py DEST')
    main(sys.argv[1])
